/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\AnonymousTemplates\Command\CreateAnonymousTemplate\CreateAnonymousTemplateCommandHandler.cs */
using BuildingBlock.Application.Abstraction;
using BuildingBlock.Application.Abstraction.Security;
using BuildingBlock.Domain.Results;
using CustomerSurvey.Application.Abstraction.Presistence;
using CustomerSurvey.Application.Abstraction.Services;
using CustomerSurvey.Domain.Entities;
using CustomerSurvey.Domain.Enums;
using CustomerSurvey.Domain.Identity;
using CustomerSurvey.Domain.Resources;

namespace CustomerSurvey.Application.Features.AnonymousTemplates.Command.CreateAnonymousTemplate
{
    internal sealed class CreateAnonymousTemplateCommandHandler
        : ICommandHandler<CreateAnonymousTemplateCommand, CreateAnonymousTemplateResponse>
    {
        private readonly IWriteReadRepository<AnonymousTemplate> _anonymousTemplateReadRepository;
        private readonly IWriteRepository<AnonymousTemplate> _anonymousTemplateWriteRepository;
        private readonly IWriteReadRepository<SuperAdmin> _superAdminReadRepository;
        private readonly IWriteReadRepository<BranchAdmin> _branchAdminReadRepository;
        private readonly IWriteReadRepository<BranchUser> _branchUserReadRepository;
        private readonly IPublicSurveyUrlBuilder _publicSurveyUrlBuilder;
        private readonly IQrCodeGenerator _qrCodeGenerator;
        private readonly ICurrentUser _currentUser;
        private readonly IUnitOfWork _unitOfWork;

        public CreateAnonymousTemplateCommandHandler(
            IWriteReadRepository<AnonymousTemplate> anonymousTemplateReadRepository,
            IWriteRepository<AnonymousTemplate> anonymousTemplateWriteRepository,
            IWriteReadRepository<SuperAdmin> superAdminReadRepository,
            IWriteReadRepository<BranchAdmin> branchAdminReadRepository,
            IWriteReadRepository<BranchUser> branchUserReadRepository,
            IPublicSurveyUrlBuilder publicSurveyUrlBuilder,
            IQrCodeGenerator qrCodeGenerator,
            ICurrentUser currentUser,
            IUnitOfWork unitOfWork)
        {
            _anonymousTemplateReadRepository = anonymousTemplateReadRepository
                ?? throw new ArgumentNullException(nameof(anonymousTemplateReadRepository));

            _anonymousTemplateWriteRepository = anonymousTemplateWriteRepository
                ?? throw new ArgumentNullException(nameof(anonymousTemplateWriteRepository));

            _superAdminReadRepository = superAdminReadRepository
                ?? throw new ArgumentNullException(nameof(superAdminReadRepository));

            _branchAdminReadRepository = branchAdminReadRepository
                ?? throw new ArgumentNullException(nameof(branchAdminReadRepository));

            _branchUserReadRepository = branchUserReadRepository
                ?? throw new ArgumentNullException(nameof(branchUserReadRepository));

            _publicSurveyUrlBuilder = publicSurveyUrlBuilder
                ?? throw new ArgumentNullException(nameof(publicSurveyUrlBuilder));

            _qrCodeGenerator = qrCodeGenerator
                ?? throw new ArgumentNullException(nameof(qrCodeGenerator));

            _currentUser = currentUser
                ?? throw new ArgumentNullException(nameof(currentUser));

            _unitOfWork = unitOfWork
                ?? throw new ArgumentNullException(nameof(unitOfWork));
        }

        public async Task<Result<CreateAnonymousTemplateResponse>> Handle(
            CreateAnonymousTemplateCommand request,
            CancellationToken cancellationToken)
        {
            if (!_currentUser.IsAuthenticated || !_currentUser.UserId.HasValue)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.Unauthenticated",
                    Message: ErrorMessage.Auth_Token_Missing,
                    Type: ErrorType.Security));
            }

            var currentApplicationUserId = _currentUser.UserId.Value;

            var currentSuperAdmin = await _superAdminReadRepository.FirstOrDefaultAsync(
                new GetCurrentSuperAdminForCreateAnonymousTemplateSpec(currentApplicationUserId),
                cancellationToken);

            if (currentSuperAdmin is not null)
            {
                return await CreateGlobalAnonymousTemplateAsync(
                    request,
                    currentApplicationUserId,
                    cancellationToken);
            }

            var currentBranchActor = await ResolveBranchActorAsync(
                currentApplicationUserId,
                cancellationToken);

            if (currentBranchActor is null)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.CurrentActorNotFound",
                    Message: ErrorMessage.CreateAnonymousTemplate_CurrentActor_NotFound,
                    Type: ErrorType.Security));
            }

            return await CreateBranchAnonymousTemplateAsync(
                request,
                currentBranchActor.BranchId,
                currentApplicationUserId,
                cancellationToken);
        }

        private async Task<Result<CreateAnonymousTemplateResponse>> CreateGlobalAnonymousTemplateAsync(
            CreateAnonymousTemplateCommand request,
            Guid currentApplicationUserId,
            CancellationToken cancellationToken)
        {
            if (request.Scope.HasValue &&
                request.Scope.Value != AnonymousTemplateScope.Global)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.SuperAdminCanCreateGlobalOnly",
                    Message: ErrorMessage.CreateAnonymousTemplate_SuperAdmin_GlobalOnly,
                    Type: ErrorType.Validation));
            }

            var normalizedNameEn = request.NameEn.Trim();

            var nameExists = await _anonymousTemplateReadRepository.AnyAsync(
                x => x.Scope == AnonymousTemplateScope.Global &&
                     x.NameEn == normalizedNameEn,
                cancellationToken);

            if (nameExists)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.NameAlreadyExists",
                    Message: ErrorMessage.CreateAnonymousTemplate_Name_AlreadyExists,
                    Type: ErrorType.Validation));
            }

            var anonymousTemplate = AnonymousTemplate.CreateGlobalTemplate(
                nameEn: request.NameEn,
                nameAr: request.NameAr,
                description: request.Description,
                activeFrom: request.ActiveFrom,
                expireTo: request.ExpireTo,
                createdByApplicationUserId: currentApplicationUserId);

            AddCustomInputs(
                anonymousTemplate,
                request.CustomInputs,
                currentApplicationUserId);

            SetPublicAccess(anonymousTemplate);

            await _anonymousTemplateWriteRepository.AddAsync(
                anonymousTemplate,
                cancellationToken);

            await _unitOfWork.SaveChangesAsync(cancellationToken);

            return Result<CreateAnonymousTemplateResponse>.Ok(
                MapToResponse(anonymousTemplate));
        }

        private async Task<Result<CreateAnonymousTemplateResponse>> CreateBranchAnonymousTemplateAsync(
            CreateAnonymousTemplateCommand request,
            Guid branchId,
            Guid currentApplicationUserId,
            CancellationToken cancellationToken)
        {
            if (request.Scope.HasValue &&
                request.Scope.Value != AnonymousTemplateScope.Branch)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.BranchActorCanCreateBranchOnly",
                    Message: ErrorMessage.CreateAnonymousTemplate_BranchActor_BranchOnly,
                    Type: ErrorType.Validation));
            }

            var normalizedNameEn = request.NameEn.Trim();

            var nameExists = await _anonymousTemplateReadRepository.AnyAsync(
                x => x.Scope == AnonymousTemplateScope.Branch &&
                     x.BranchId == branchId &&
                     x.NameEn == normalizedNameEn,
                cancellationToken);

            if (nameExists)
            {
                return Result<CreateAnonymousTemplateResponse>.Fail(new Error(
                    Code: "AnonymousTemplates.Create.NameAlreadyExists",
                    Message: ErrorMessage.CreateAnonymousTemplate_Name_AlreadyExists,
                    Type: ErrorType.Validation));
            }

            var anonymousTemplate = AnonymousTemplate.CreateBranchTemplate(
                branchId: branchId,
                nameEn: request.NameEn,
                nameAr: request.NameAr,
                description: request.Description,
                activeFrom: request.ActiveFrom,
                expireTo: request.ExpireTo,
                createdByApplicationUserId: currentApplicationUserId);

            AddCustomInputs(
                anonymousTemplate,
                request.CustomInputs,
                currentApplicationUserId);

            SetPublicAccess(anonymousTemplate);

            await _anonymousTemplateWriteRepository.AddAsync(
                anonymousTemplate,
                cancellationToken);

            await _unitOfWork.SaveChangesAsync(cancellationToken);

            return Result<CreateAnonymousTemplateResponse>.Ok(
                MapToResponse(anonymousTemplate));
        }

        private async Task<CurrentBranchActorForCreateAnonymousTemplateDto?> ResolveBranchActorAsync(
            Guid applicationUserId,
            CancellationToken cancellationToken)
        {
            var currentBranchAdmin = await _branchAdminReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchAdminForCreateAnonymousTemplateSpec(applicationUserId),
                cancellationToken);

            if (currentBranchAdmin is not null)
            {
                return currentBranchAdmin;
            }

            var currentBranchUser = await _branchUserReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchUserForCreateAnonymousTemplateSpec(applicationUserId),
                cancellationToken);

            return currentBranchUser;
        }

        private void SetPublicAccess(AnonymousTemplate anonymousTemplate)
        {
            var publicUrl = _publicSurveyUrlBuilder.BuildAnonymousTemplateUrl(
                anonymousTemplate.Id);

            var qrCode = _qrCodeGenerator.GenerateBase64Png(publicUrl);

            anonymousTemplate.SetPublicAccess(
                publicUrl: publicUrl,
                qrCode: qrCode);
        }

        private static void AddCustomInputs(
            AnonymousTemplate anonymousTemplate,
            IReadOnlyCollection<CreateAnonymousTemplateCustomInputCommandItem> customInputs,
            Guid currentApplicationUserId)
        {
            foreach (var input in customInputs.OrderBy(x => x.Order))
            {
                var customInput = AnonymousTemplateCustomInput.Create(
                    anonymousTemplateId: anonymousTemplate.Id,
                    name: input.Name,
                    labelEn: input.LabelEn,
                    labelAr: input.LabelAr,
                    type: input.Type,
                    isRequired: input.IsRequired,
                    minLength: input.MinLength,
                    maxLength: input.MaxLength,
                    minValue: input.MinValue,
                    maxValue: input.MaxValue,
                    order: input.Order,
                    createdByApplicationUserId: currentApplicationUserId);

                anonymousTemplate.AddCustomInput(customInput);
            }
        }

        private static CreateAnonymousTemplateResponse MapToResponse(
            AnonymousTemplate anonymousTemplate)
        {
            return new CreateAnonymousTemplateResponse
            {
                AnonymousTemplateId = anonymousTemplate.Id,
                BranchId = anonymousTemplate.BranchId,
                Scope = anonymousTemplate.Scope,
                ScopeName = anonymousTemplate.Scope.ToString(),
                IsGlobal = anonymousTemplate.Scope == AnonymousTemplateScope.Global,
                NameEn = anonymousTemplate.NameEn,
                NameAr = anonymousTemplate.NameAr,
                Description = anonymousTemplate.Description,
                ActiveFrom = anonymousTemplate.ActiveFrom,
                ExpireTo = anonymousTemplate.ExpireTo,
                Status = anonymousTemplate.Status,
                StatusName = anonymousTemplate.Status.ToString(),
                IsActive = anonymousTemplate.IsActive,
                PublicUrl = anonymousTemplate.PublicUrl,
                QrCode = anonymousTemplate.QrCode,
                CreatedByApplicationUserId = anonymousTemplate.CreatedByApplicationUserId,
                CustomInputs = anonymousTemplate.CustomInputs
                    .OrderBy(x => x.Order)
                    .Select(x => new CreateAnonymousTemplateCustomInputResponse
                    {
                        CustomInputId = x.Id,
                        Name = x.Name,
                        LabelEn = x.LabelEn,
                        LabelAr = x.LabelAr,
                        Type = x.Type,
                        TypeName = x.Type.ToString(),
                        IsRequired = x.IsRequired,
                        MinLength = x.MinLength,
                        MaxLength = x.MaxLength,
                        MinValue = x.MinValue,
                        MaxValue = x.MaxValue,
                        Order = x.Order,
                        IsActive = x.IsActive
                    })
                    .ToArray()
            };
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\AnonymousTemplates\Command\CreateAnonymousTemplate\CreateAnonymousTemplateCommandValidator.cs */
using CustomerSurvey.Domain.Enums;
using CustomerSurvey.Domain.Resources;
using FluentValidation;

namespace CustomerSurvey.Application.Features.AnonymousTemplates.Command.CreateAnonymousTemplate
{
    internal sealed class CreateAnonymousTemplateCommandValidator
        : AbstractValidator<CreateAnonymousTemplateCommand>
    {
        public CreateAnonymousTemplateCommandValidator()
        {
            RuleFor(x => x.NameEn)
                .NotEmpty()
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_NameEn_Required)
                .MaximumLength(200)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_NameEn_MaxLength);

            RuleFor(x => x.NameAr)
                .MaximumLength(200)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_NameAr_MaxLength)
                .When(x => !string.IsNullOrWhiteSpace(x.NameAr));

            RuleFor(x => x.Description)
                .MaximumLength(1000)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_Description_MaxLength)
                .When(x => !string.IsNullOrWhiteSpace(x.Description));

            RuleFor(x => x.ActiveFrom)
                .NotEmpty()
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_ActiveFrom_Required);

            RuleFor(x => x)
                .Must(x => !x.ExpireTo.HasValue || x.ExpireTo.Value > x.ActiveFrom)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_ExpireTo_MustBeAfterActiveFrom);

            RuleFor(x => x.Scope)
                .Must(x => !x.HasValue ||
                           x.Value == AnonymousTemplateScope.Branch ||
                           x.Value == AnonymousTemplateScope.Global)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_Scope_Invalid);

            RuleFor(x => x.CustomInputs)
                .Must(x => x is not null)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInputs_Invalid);

            RuleForEach(x => x.CustomInputs)
                .ChildRules(input =>
                {
                    input.RuleFor(x => x.Name)
                        .NotEmpty()
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Name_Required)
                        .MaximumLength(100)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Name_MaxLength);

                    input.RuleFor(x => x.LabelEn)
                        .MaximumLength(200)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_LabelEn_MaxLength)
                        .When(x => !string.IsNullOrWhiteSpace(x.LabelEn));

                    input.RuleFor(x => x.LabelAr)
                        .MaximumLength(200)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_LabelAr_MaxLength)
                        .When(x => !string.IsNullOrWhiteSpace(x.LabelAr));

                    input.RuleFor(x => x.Type)
                        .IsInEnum()
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Type_Invalid);

                    input.RuleFor(x => x.Order)
                        .GreaterThan(0)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Order_Invalid);

                    input.RuleFor(x => x)
                        .Must(ValidateStringValidationShape)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_StringValidation_Invalid);

                    input.RuleFor(x => x)
                        .Must(ValidateIntegerValidationShape)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_IntegerValidation_Invalid);

                    input.RuleFor(x => x)
                        .Must(x => !x.MinLength.HasValue || !x.MaxLength.HasValue || x.MaxLength.Value >= x.MinLength.Value)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_LengthRange_Invalid);

                    input.RuleFor(x => x)
                        .Must(x => !x.MinValue.HasValue || !x.MaxValue.HasValue || x.MaxValue.Value >= x.MinValue.Value)
                        .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_ValueRange_Invalid);
                });

            RuleFor(x => x.CustomInputs)
                .Must(HaveUniqueInputNames)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Name_Duplicated);

            RuleFor(x => x.CustomInputs)
                .Must(HaveUniqueOrders)
                .WithMessage(ErrorMessage.CreateAnonymousTemplate_CustomInput_Order_Duplicated);
        }

        private static bool ValidateStringValidationShape(
            CreateAnonymousTemplateCustomInputCommandItem input)
        {
            if (input.Type != TemplateCustomInputType.String)
            {
                return true;
            }

            return !input.MinValue.HasValue && !input.MaxValue.HasValue;
        }

        private static bool ValidateIntegerValidationShape(
            CreateAnonymousTemplateCustomInputCommandItem input)
        {
            if (input.Type != TemplateCustomInputType.Integer)
            {
                return true;
            }

            return !input.MinLength.HasValue && !input.MaxLength.HasValue;
        }

        private static bool HaveUniqueInputNames(
            IReadOnlyCollection<CreateAnonymousTemplateCustomInputCommandItem> inputs)
        {
            var normalizedNames = inputs
                .Where(x => !string.IsNullOrWhiteSpace(x.Name))
                .Select(x => x.Name.Trim().ToLowerInvariant())
                .ToArray();

            return normalizedNames.Length == normalizedNames.Distinct().Count();
        }

        private static bool HaveUniqueOrders(
            IReadOnlyCollection<CreateAnonymousTemplateCustomInputCommandItem> inputs)
        {
            var orders = inputs
                .Where(x => x.Order > 0)
                .Select(x => x.Order)
                .ToArray();

            return orders.Length == orders.Distinct().Count();
        }
    }
}
