using BuildingBlock.Application.Abstraction;
using BuildingBlock.Application.Abstraction.Security;
using BuildingBlock.Domain.Results;
using BuildingBlock.Domain.SharedDto;
using CustomerSurvey.Application.Abstraction.Presistence;
using CustomerSurvey.Domain.Entities;
using CustomerSurvey.Domain.Identity;
using CustomerSurvey.Domain.Resources;

namespace CustomerSurvey.Application.Features.AnonymousTemplates.Query.GetAnonymousTemplateResponsesPagination
{
    internal sealed class GetAnonymousTemplateResponsesPaginationQueryHandler
        : IQueryHandler<GetAnonymousTemplateResponsesPaginationQuery, Pagination<AnonymousTemplateResponsePaginationItemResponse>>
    {
        private readonly IWriteReadRepository<AnonymousTemplate> _anonymousTemplateReadRepository;
        private readonly IWriteReadRepository<AnonymousSurveyResponse> _anonymousSurveyResponseReadRepository;
        private readonly IWriteReadRepository<SuperAdmin> _superAdminReadRepository;
        private readonly IWriteReadRepository<BranchAdmin> _branchAdminReadRepository;
        private readonly IWriteReadRepository<BranchUser> _branchUserReadRepository;
        private readonly ICurrentUser _currentUser;

        public GetAnonymousTemplateResponsesPaginationQueryHandler(
            IWriteReadRepository<AnonymousTemplate> anonymousTemplateReadRepository,
            IWriteReadRepository<AnonymousSurveyResponse> anonymousSurveyResponseReadRepository,
            IWriteReadRepository<SuperAdmin> superAdminReadRepository,
            IWriteReadRepository<BranchAdmin> branchAdminReadRepository,
            IWriteReadRepository<BranchUser> branchUserReadRepository,
            ICurrentUser currentUser)
        {
            _anonymousTemplateReadRepository = anonymousTemplateReadRepository
                ?? throw new ArgumentNullException(nameof(anonymousTemplateReadRepository));

            _anonymousSurveyResponseReadRepository = anonymousSurveyResponseReadRepository
                ?? throw new ArgumentNullException(nameof(anonymousSurveyResponseReadRepository));

            _superAdminReadRepository = superAdminReadRepository
                ?? throw new ArgumentNullException(nameof(superAdminReadRepository));

            _branchAdminReadRepository = branchAdminReadRepository
                ?? throw new ArgumentNullException(nameof(branchAdminReadRepository));

            _branchUserReadRepository = branchUserReadRepository
                ?? throw new ArgumentNullException(nameof(branchUserReadRepository));

            _currentUser = currentUser
                ?? throw new ArgumentNullException(nameof(currentUser));
        }

        public async Task<Result<Pagination<AnonymousTemplateResponsePaginationItemResponse>>> Handle(
            GetAnonymousTemplateResponsesPaginationQuery request,
            CancellationToken cancellationToken)
        {
            if (!_currentUser.IsAuthenticated || !_currentUser.UserId.HasValue)
            {
                return Result<Pagination<AnonymousTemplateResponsePaginationItemResponse>>.Fail(new Error(
                    Code: "AnonymousTemplates.ResponsesPagination.Unauthenticated",
                    Message: ErrorMessage.Auth_Token_Missing,
                    Type: ErrorType.Security));
            }

            request.SearchText ??= string.Empty;

            var currentApplicationUserId = _currentUser.UserId.Value;

            var isSuperAdmin = await _superAdminReadRepository.AnyAsync(
                x => x.ApplicationUserId == currentApplicationUserId,
                cancellationToken);

            Guid? currentBranchId = null;

            if (!isSuperAdmin)
            {
                var currentBranchActor = await ResolveBranchActorAsync(
                    currentApplicationUserId,
                    cancellationToken);

                if (currentBranchActor is null)
                {
                    return Result<Pagination<AnonymousTemplateResponsePaginationItemResponse>>.Fail(new Error(
                        Code: "AnonymousTemplates.ResponsesPagination.CurrentActorNotFound",
                        Message: ErrorMessage.GetAnonymousTemplateResponsesPagination_CurrentActor_NotFound,
                        Type: ErrorType.Security));
                }

                currentBranchId = currentBranchActor.BranchId;
            }

            var anonymousTemplate = await _anonymousTemplateReadRepository.FirstOrDefaultAsync(
                new GetAnonymousTemplateForResponsesPaginationSpec(
                    request.AnonymousTemplateId,
                    isSuperAdmin,
                    currentBranchId),
                cancellationToken);

            if (anonymousTemplate is null)
            {
                return Result<Pagination<AnonymousTemplateResponsePaginationItemResponse>>.Fail(new Error(
                    Code: "AnonymousTemplates.ResponsesPagination.TemplateNotFound",
                    Message: ErrorMessage.GetAnonymousTemplateResponsesPagination_Template_NotFound,
                    Type: ErrorType.NotFound));
            }

            var spec = new GetAnonymousTemplateResponsesPaginationSpec(request);

            var (items, totalCount) = await _anonymousSurveyResponseReadRepository.ListWithCountAsync(
                spec,
                cancellationToken);

            var response = new Pagination<AnonymousTemplateResponsePaginationItemResponse>(
                currentPage: request.PageNumber,
                pageSize: request.PageSize,
                totalItems: totalCount,
                data: items);

            return Result<Pagination<AnonymousTemplateResponsePaginationItemResponse>>.Ok(response);
        }

        private async Task<CurrentBranchActorForGetAnonymousTemplateResponsesPaginationDto?> ResolveBranchActorAsync(
            Guid applicationUserId,
            CancellationToken cancellationToken)
        {
            var currentBranchAdmin = await _branchAdminReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchAdminForAnonymousTemplateResponsesPaginationSpec(applicationUserId),
                cancellationToken);

            if (currentBranchAdmin is not null)
            {
                return currentBranchAdmin;
            }

            var currentBranchUser = await _branchUserReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchUserForAnonymousTemplateResponsesPaginationSpec(applicationUserId),
                cancellationToken);

            return currentBranchUser;
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\AnonymousTemplates\Query\GetAnonymousTemplateResponsesPagination\GetAnonymousTemplateResponsesPaginationQueryValidator.cs */
using CustomerSurvey.Domain.Resources;
using FluentValidation;

namespace CustomerSurvey.Application.Features.AnonymousTemplates.Query.GetAnonymousTemplateResponsesPagination
{
    internal sealed class GetAnonymousTemplateResponsesPaginationQueryValidator
        : AbstractValidator<GetAnonymousTemplateResponsesPaginationQuery>
    {
        public GetAnonymousTemplateResponsesPaginationQueryValidator()
        {
            RuleFor(x => x.AnonymousTemplateId)
                .NotEmpty()
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_AnonymousTemplateId_Required);

            RuleFor(x => x.PageNumber)
                .GreaterThanOrEqualTo(1)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_PageNumber_Invalid);

            RuleFor(x => x.PageSize)
                .GreaterThanOrEqualTo(1)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_PageSize_Invalid)
                .LessThanOrEqualTo(100)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_PageSize_Max);

            RuleFor(x => x)
                .Must(x => !x.FromDate.HasValue ||
                           !x.ToDate.HasValue ||
                           x.ToDate.Value > x.FromDate.Value)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_DateRange_Invalid);

            RuleFor(x => x.MinScorePercentage)
                .InclusiveBetween(0, 100)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_MinScorePercentage_Invalid)
                .When(x => x.MinScorePercentage.HasValue);

            RuleFor(x => x.MaxScorePercentage)
                .InclusiveBetween(0, 100)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_MaxScorePercentage_Invalid)
                .When(x => x.MaxScorePercentage.HasValue);

            RuleFor(x => x)
                .Must(x => !x.MinScorePercentage.HasValue ||
                           !x.MaxScorePercentage.HasValue ||
                           x.MaxScorePercentage.Value >= x.MinScorePercentage.Value)
                .WithMessage(ErrorMessage.GetAnonymousTemplateResponsesPagination_ScoreRange_Invalid);
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\AnonymousTemplates\Query\GetAnonymousTemplateResponsesPagination\GetAnonymousTemplateResponsesPaginationSpec.cs */
using BuildingBlock.Domain.Enums;
using BuildingBlock.Domain.Specification;
using CustomerSurvey.Domain.Entities;

namespace CustomerSurvey.Application.Features.AnonymousTemplates.Query.GetAnonymousTemplateResponsesPagination
{
    internal sealed class GetAnonymousTemplateResponsesPaginationSpec
        : Specification<AnonymousSurveyResponse, AnonymousTemplateResponsePaginationItemResponse>
    {
        public GetAnonymousTemplateResponsesPaginationSpec(
            GetAnonymousTemplateResponsesPaginationQuery request)
        {
            AddCriteria(x => x.AnonymousTemplateId == request.AnonymousTemplateId);

            if (request.FromDate.HasValue)
            {
                AddCriteria(x => x.SubmittedOnUtc >= request.FromDate.Value);
            }

            if (request.ToDate.HasValue)
            {
                AddCriteria(x => x.SubmittedOnUtc < request.ToDate.Value);
            }

            if (request.MinScorePercentage.HasValue)
            {
                AddCriteria(x => x.ScorePercentage >= request.MinScorePercentage.Value);
            }

            if (request.MaxScorePercentage.HasValue)
            {
                AddCriteria(x => x.ScorePercentage <= request.MaxScorePercentage.Value);
            }

            if (request.OrderSort == OrderSort.Oldest)
            {
                AddOrderBy(x => x.SubmittedOnUtc);
            }
            else
            {
                AddOrderByDescending(x => x.SubmittedOnUtc);
            }

            EnableTotalCount();

            ApplyPaging(
                request.PageNumber,
                request.PageSize);

            Select(x => new AnonymousTemplateResponsePaginationItemResponse
            {
                AnonymousSurveyResponseId = x.Id,
                AnonymousTemplateId = x.AnonymousTemplateId,
                SubmittedOnUtc = x.SubmittedOnUtc,

                ActualScore = x.ActualScore,
                MaxScore = x.MaxScore,
                ScorePercentage = x.ScorePercentage,
                IsScored = x.MaxScore > 0,

                AnswersCount = x.Answers.Count,
                CustomInputValuesCount = x.CustomInputValues.Count
            });
        }
    }
}
