using CustomerSurvey.Domain.Resources;
using FluentValidation;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.Application.Features.Questions.Query.GetQuestionsPagination
{
    internal sealed class GetQuestionsPaginationQueryValidator
        : AbstractValidator<GetQuestionsPaginationQuery>
    {
        public GetQuestionsPaginationQueryValidator()
        {
            RuleFor(x => x.PageNumber)
                .GreaterThanOrEqualTo(1)
                .WithMessage(ErrorMessage.GetQuestionsPagination_PageNumber_Invalid);

            RuleFor(x => x.PageSize)
                .GreaterThanOrEqualTo(1)
                .WithMessage(ErrorMessage.GetQuestionsPagination_PageSize_Invalid)
                .LessThanOrEqualTo(100)
                .WithMessage(ErrorMessage.GetQuestionsPagination_PageSize_Max);
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\Questions\Query\GetQuestionsPagination\GetQuestionsPaginationSpec.cs */
using BuildingBlock.Domain.Enums;
using BuildingBlock.Domain.Specification;
using CustomerSurvey.Domain.Entities;

namespace CustomerSurvey.Application.Features.Questions.Query.GetQuestionsPagination
{
    internal sealed class GetQuestionsPaginationSpec
       : Specification<Question, QuestionPaginationItemDto>
    {
        public GetQuestionsPaginationSpec(
            Guid branchId,
            GetQuestionsPaginationQuery searchParameters)
        {
            AddCriteria(x => x.BranchId == branchId);

            if (searchParameters.IsActive.HasValue)
            {
                AddCriteria(x => x.IsActive == searchParameters.IsActive.Value);
            }

            if (!string.IsNullOrWhiteSpace(searchParameters.SearchText))
            {
                var searchText = searchParameters.SearchText.Trim();

                AddCriteria(x =>
                    x.TextEn.Contains(searchText) ||
                    (x.TextAr != null && x.TextAr.Contains(searchText)) ||
                    x.Group.NameEn.Contains(searchText) ||
                    (x.Group.NameAr != null && x.Group.NameAr.Contains(searchText)));
            }

            if (searchParameters.OrderSort == OrderSort.Oldest)
            {
                AddOrderByDescending(x => x.CreatedOnUtc);
            }
            else
            {
                AddOrderBy(x => x.CreatedOnUtc);
            }

            EnableTotalCount();

            ApplyPaging(
                searchParameters.PageNumber,
                searchParameters.PageSize);

            Select(x => new QuestionPaginationItemDto
            {
                QuestionId = x.Id,
                BranchId = x.BranchId,
                GroupId = x.GroupId,
                GroupNameEn = x.Group.NameEn,
                GroupNameAr = x.Group.NameAr,
                TextEn = x.TextEn,
                TextAr = x.TextAr,
                Type = x.Type,
                TypeName = x.Type.ToString(),
                IsActive = x.IsActive,
                CreatedByApplicationUserId = x.CreatedByApplicationUserId,
                CreatedOnUtc = x.CreatedOnUtc
            });
        }
    }
}
