using BuildingBlock.Application.Abstraction;
using BuildingBlock.Application.Abstraction.Security;
using BuildingBlock.Domain.Results;
using CustomerSurvey.Application.Abstraction.Presistence;
using CustomerSurvey.Domain.Entities;
using CustomerSurvey.Domain.Identity;
using CustomerSurvey.Domain.Resources;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.Application.Features.Templates.Command.CreateTemplate
{
    internal sealed class CreateTemplateCommandHandler
         : ICommandHandler<CreateTemplateCommand, CreateTemplateResponse>
    {
        private readonly IWriteReadRepository<Template> _templateReadRepository;
        private readonly IWriteRepository<Template> _templateWriteRepository;

        private readonly IWriteReadRepository<BranchAdmin> _branchAdminReadRepository;
        private readonly IWriteReadRepository<BranchUser> _branchUserReadRepository;

        private readonly ICurrentUser _currentUser;
        private readonly IUnitOfWork _unitOfWork;

        public CreateTemplateCommandHandler(
            IWriteReadRepository<Template> templateReadRepository,
            IWriteRepository<Template> templateWriteRepository,
            IWriteReadRepository<BranchAdmin> branchAdminReadRepository,
            IWriteReadRepository<BranchUser> branchUserReadRepository,
            ICurrentUser currentUser,
            IUnitOfWork unitOfWork)
        {
            _templateReadRepository = templateReadRepository
                ?? throw new ArgumentNullException(nameof(templateReadRepository));

            _templateWriteRepository = templateWriteRepository
                ?? throw new ArgumentNullException(nameof(templateWriteRepository));

            _branchAdminReadRepository = branchAdminReadRepository
                ?? throw new ArgumentNullException(nameof(branchAdminReadRepository));

            _branchUserReadRepository = branchUserReadRepository
                ?? throw new ArgumentNullException(nameof(branchUserReadRepository));

            _currentUser = currentUser
                ?? throw new ArgumentNullException(nameof(currentUser));

            _unitOfWork = unitOfWork
                ?? throw new ArgumentNullException(nameof(unitOfWork));
        }

        public async Task<Result<CreateTemplateResponse>> Handle(
            CreateTemplateCommand request,
            CancellationToken cancellationToken)
        {
            if (!_currentUser.IsAuthenticated || !_currentUser.UserId.HasValue)
            {
                return Result<CreateTemplateResponse>.Fail(new Error(
                    Code: "Templates.Create.Unauthenticated",
                    Message: ErrorMessage.Auth_Token_Missing,
                    Type: ErrorType.Security));
            }

            var currentApplicationUserId = _currentUser.UserId.Value;

            var actorBranchIdResult = await ResolveCurrentActorBranchIdAsync(
                currentApplicationUserId,
                cancellationToken);

            if (actorBranchIdResult.IsFailure)
            {
                return Result<CreateTemplateResponse>.Fail(actorBranchIdResult.Errors);
            }

            var branchId = actorBranchIdResult.Value;

            var normalizedNameEn = request.NameEn.Trim();

            var templateNameExists = await _templateReadRepository.AnyAsync(
                x => x.BranchId == branchId && x.NameEn == normalizedNameEn,
                cancellationToken);

            if (templateNameExists)
            {
                return Result<CreateTemplateResponse>.Fail(new Error(
                    Code: "Templates.Create.NameEnAlreadyExistsInsideBranch",
                    Message: ErrorMessage.CreateTemplate_NameEn_AlreadyExists_InsideBranch,
                    Type: ErrorType.Validation));
            }

            var template = Template.Create(
                branchId: branchId,
                nameEn: normalizedNameEn,
                nameAr: request.NameAr,
                description: request.Description,
                activeFrom: request.ActiveFrom,
                expireTo: request.ExpireTo,
                createdByApplicationUserId: currentApplicationUserId);

            foreach (var customInputRequest in request.CustomInputs.OrderBy(x => x.Order))
            {
                var customInput = TemplateCustomInput.Create(
                    templateId: template.Id,
                    name: customInputRequest.Name,
                    labelEn: customInputRequest.LabelEn,
                    labelAr: customInputRequest.LabelAr,
                    type: customInputRequest.Type,
                    isRequired: customInputRequest.IsRequired,
                    minLength: customInputRequest.MinLength,
                    maxLength: customInputRequest.MaxLength,
                    minValue: customInputRequest.MinValue,
                    maxValue: customInputRequest.MaxValue,
                    order: customInputRequest.Order,
                    createdByApplicationUserId: currentApplicationUserId);

                template.AddCustomInput(customInput);
            }

            await _templateWriteRepository.AddAsync(template, cancellationToken);

            await _unitOfWork.SaveChangesAsync(cancellationToken);

            var response = new CreateTemplateResponse
            {
                TemplateId = template.Id,
                BranchId = template.BranchId,
                NameEn = template.NameEn,
                NameAr = template.NameAr,
                Description = template.Description,
                ActiveFrom = template.ActiveFrom,
                ExpireTo = template.ExpireTo,
                Status = template.Status.ToString(),
                IsActive = template.IsActive,
                CustomInputs = template.CustomInputs
                    .OrderBy(x => x.Order)
                    .Select(x => new CreateTemplateCustomInputResponse
                    {
                        CustomInputId = x.Id,
                        Name = x.Name,
                        LabelEn = x.LabelEn,
                        LabelAr = x.LabelAr,
                        Type = x.Type,
                        IsRequired = x.IsRequired,
                        MinLength = x.MinLength,
                        MaxLength = x.MaxLength,
                        MinValue = x.MinValue,
                        MaxValue = x.MaxValue,
                        Order = x.Order,
                        IsActive = x.IsActive
                    })
                    .ToArray()
            };

            return Result<CreateTemplateResponse>.Ok(response);
        }

        private async Task<Result<Guid>> ResolveCurrentActorBranchIdAsync(
            Guid currentApplicationUserId,
            CancellationToken cancellationToken)
        {
            var branchAdmin = await _branchAdminReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchAdminForCreateTemplateSpec(currentApplicationUserId),
                cancellationToken);

            if (branchAdmin is not null)
            {
                return Result<Guid>.Ok(branchAdmin.BranchId);
            }

            var branchUser = await _branchUserReadRepository.FirstOrDefaultAsync(
                new GetCurrentBranchUserForCreateTemplateSpec(currentApplicationUserId),
                cancellationToken);

            if (branchUser is not null)
            {
                return Result<Guid>.Ok(branchUser.BranchId);
            }

            return Result<Guid>.Fail(new Error(
                Code: "Templates.Create.CurrentBranchActorNotFound",
                Message: ErrorMessage.CreateTemplate_CurrentBranchActor_NotFound,
                Type: ErrorType.Security));
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Application\Features\Templates\Command\CreateTemplate\CreateTemplateCommandValidator.cs */
using CustomerSurvey.Domain.Enums;
using CustomerSurvey.Domain.Resources;
using FluentValidation;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.Application.Features.Templates.Command.CreateTemplate
{
    internal sealed class CreateTemplateCommandValidator
         : AbstractValidator<CreateTemplateCommand>
    {
        private const int CustomInputNameMaxLength = 100;
        private const int CustomInputLabelMaxLength = 200;
        private const int CustomInputStringMaxLength = 3000;

        public CreateTemplateCommandValidator()
        {
            RuleFor(x => x.NameEn)
                .NotEmpty()
                .WithMessage(ErrorMessage.CreateTemplate_NameEn_Required)
                .MaximumLength(200)
                .WithMessage(ErrorMessage.CreateTemplate_NameEn_MaxLength);

            RuleFor(x => x.NameAr)
                .MaximumLength(200)
                .WithMessage(ErrorMessage.CreateTemplate_NameAr_MaxLength)
                .When(x => !string.IsNullOrWhiteSpace(x.NameAr));

            RuleFor(x => x.Description)
                .MaximumLength(1000)
                .WithMessage(ErrorMessage.CreateTemplate_Description_MaxLength)
                .When(x => !string.IsNullOrWhiteSpace(x.Description));

            RuleFor(x => x.ActiveFrom)
                .NotEmpty()
                .WithMessage(ErrorMessage.CreateTemplate_ActiveFrom_Required);

            RuleFor(x => x)
                .Must(x => !x.ExpireTo.HasValue || x.ExpireTo.Value > x.ActiveFrom)
                .WithMessage(ErrorMessage.CreateTemplate_ExpireTo_MustBeAfterActiveFrom);

            RuleFor(x => x.CustomInputs)
                .NotNull()
                .WithMessage(ErrorMessage.CreateTemplate_CustomInputs_Invalid);

            RuleFor(x => x.CustomInputs)
                .Must(HaveUniqueCustomInputNames)
                .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Name_Duplicated)
                .When(x => x.CustomInputs is not null && x.CustomInputs.Count > 0);

            RuleFor(x => x.CustomInputs)
                .Must(HaveUniqueCustomInputOrders)
                .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Order_Duplicated)
                .When(x => x.CustomInputs is not null && x.CustomInputs.Count > 0);

            RuleForEach(x => x.CustomInputs)
                .ChildRules(customInput =>
                {
                    customInput.RuleFor(x => x.Name)
                        .NotEmpty()
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Name_Required)
                        .MaximumLength(CustomInputNameMaxLength)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Name_MaxLength);

                    customInput.RuleFor(x => x.LabelEn)
                        .MaximumLength(CustomInputLabelMaxLength)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_LabelEn_MaxLength)
                        .When(x => !string.IsNullOrWhiteSpace(x.LabelEn));

                    customInput.RuleFor(x => x.LabelAr)
                        .MaximumLength(CustomInputLabelMaxLength)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_LabelAr_MaxLength)
                        .When(x => !string.IsNullOrWhiteSpace(x.LabelAr));

                    customInput.RuleFor(x => x.Type)
                        .IsInEnum()
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Type_Invalid);

                    customInput.RuleFor(x => x.Order)
                        .GreaterThan(0)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_Order_Invalid);

                    customInput.RuleFor(x => x)
                        .Must(BeValidStringValidation)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_StringValidation_Invalid)
                        .When(x => x.Type == TemplateCustomInputType.String);

                    customInput.RuleFor(x => x)
                        .Must(BeValidIntegerValidation)
                        .WithMessage(ErrorMessage.CreateTemplate_CustomInput_IntegerValidation_Invalid)
                        .When(x => x.Type == TemplateCustomInputType.Integer);
                });
        }

        private static bool HaveUniqueCustomInputNames(
            IReadOnlyCollection<CreateTemplateCustomInputCommandItem> customInputs)
        {
            var names = customInputs
                .Where(x => !string.IsNullOrWhiteSpace(x.Name))
                .Select(x => x.Name.Trim().ToLowerInvariant())
                .ToArray();

            return names.Length == names.Distinct().Count();
        }

        private static bool HaveUniqueCustomInputOrders(
            IReadOnlyCollection<CreateTemplateCustomInputCommandItem> customInputs)
        {
            var orders = customInputs
                .Select(x => x.Order)
                .Where(x => x > 0)
                .ToArray();

            return orders.Length == orders.Distinct().Count();
        }

        private static bool BeValidStringValidation(CreateTemplateCustomInputCommandItem customInput)
        {
            if (customInput.MinValue.HasValue || customInput.MaxValue.HasValue)
            {
                return false;
            }

            if (customInput.MinLength.HasValue && customInput.MinLength.Value < 0)
            {
                return false;
            }

            if (customInput.MaxLength.HasValue &&
                (customInput.MaxLength.Value <= 0 || customInput.MaxLength.Value > CustomInputStringMaxLength))
            {
                return false;
            }

            if (customInput.MinLength.HasValue &&
                customInput.MaxLength.HasValue &&
                customInput.MaxLength.Value < customInput.MinLength.Value)
            {
                return false;
            }

            return true;
        }

        private static bool BeValidIntegerValidation(CreateTemplateCustomInputCommandItem customInput)
        {
            if (customInput.MinLength.HasValue || customInput.MaxLength.HasValue)
            {
                return false;
            }

            if (customInput.MinValue.HasValue &&
                customInput.MaxValue.HasValue &&
                customInput.MaxValue.Value < customInput.MinValue.Value)
            {
                return false;
            }

            return true;
        }
    }
}
