        {
            AddCriteria(x =>
                x.IsActive &&
                (
                    (x.Scope == QuestionScope.Branch && x.BranchId == branchId) ||
                    (x.Scope == QuestionScope.Global && x.BranchId == null)
                ));

            AddOrderBy(x => x.NameEn);

            Select(x => new QuestionGroupForTemplateQuestionsSelectionDto
            {
                GroupId = x.Id,
                BranchId = x.BranchId,
                Scope = x.Scope,
                NameEn = x.NameEn,
                NameAr = x.NameAr
            });
        }
    }
