            AddOrderBy(x => x.NameEn);

            Select(x => new TemplateSelectionResponse
            {
                Id = x.Id,
                NameEn = x.NameEn,
                NameAr = x.NameAr,
                BranchId = x.BranchId,
                BranchNameEn = x.Branch.NameEn,
                BranchNameAr = x.Branch.NameAr,
                BranchCode = x.Branch.Code,
                ActiveFrom = x.ActiveFrom,
                ExpireTo = x.ExpireTo
            });
        }
    }
}
