using BuildingBlock.Domain.EntitiesHelper;
using CustomerSurvey.Domain.Enums;

namespace CustomerSurvey.Domain.Entities
{
    public sealed class AnonymousTemplateCustomInput : Entity<Guid>
    {
        public Guid AnonymousTemplateId { get; private set; }
        public AnonymousTemplate AnonymousTemplate { get; private set; } = null!;

        public string Name { get; private set; } = string.Empty;
        public string? LabelEn { get; private set; }
        public string? LabelAr { get; private set; }

        public TemplateCustomInputType Type { get; private set; }

        public bool IsRequired { get; private set; }

        public int? MinLength { get; private set; }
        public int? MaxLength { get; private set; }

        public int? MinValue { get; private set; }
        public int? MaxValue { get; private set; }

        public int Order { get; private set; }

        public bool IsActive { get; private set; }

        public Guid CreatedByApplicationUserId { get; private set; }

        private AnonymousTemplateCustomInput()
        {
        }

        public static AnonymousTemplateCustomInput Create(
            Guid anonymousTemplateId,
            string name,
            string? labelEn,
            string? labelAr,
            TemplateCustomInputType type,
            bool isRequired,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue,
            int order,
            Guid createdByApplicationUserId)
        {
            var normalizedValidation = NormalizeValidationByType(
                type,
                minLength,
                maxLength,
                minValue,
                maxValue);

            return new AnonymousTemplateCustomInput
            {
                Id = Guid.NewGuid(),
                AnonymousTemplateId = anonymousTemplateId,
                Name = name.Trim(),
                LabelEn = string.IsNullOrWhiteSpace(labelEn) ? null : labelEn.Trim(),
                LabelAr = string.IsNullOrWhiteSpace(labelAr) ? null : labelAr.Trim(),
                Type = type,
                IsRequired = isRequired,
                MinLength = normalizedValidation.MinLength,
                MaxLength = normalizedValidation.MaxLength,
                MinValue = normalizedValidation.MinValue,
                MaxValue = normalizedValidation.MaxValue,
                Order = order,
                IsActive = true,
                CreatedByApplicationUserId = createdByApplicationUserId
            };
        }

        public void Update(
            string name,
            string? labelEn,
            string? labelAr,
            TemplateCustomInputType type,
            bool isRequired,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue,
            int order)
        {
            var normalizedValidation = NormalizeValidationByType(
                type,
                minLength,
                maxLength,
                minValue,
                maxValue);

            Name = name.Trim();
            LabelEn = string.IsNullOrWhiteSpace(labelEn) ? null : labelEn.Trim();
            LabelAr = string.IsNullOrWhiteSpace(labelAr) ? null : labelAr.Trim();
            Type = type;
            IsRequired = isRequired;
            MinLength = normalizedValidation.MinLength;
            MaxLength = normalizedValidation.MaxLength;
            MinValue = normalizedValidation.MinValue;
            MaxValue = normalizedValidation.MaxValue;
            Order = order;
        }

        public void ChangeOrder(int order)
        {
            Order = order;
        }

        public void Deactivate()
        {
            IsActive = false;
        }

        public void Restore()
        {
            IsActive = true;
        }

        private static CustomInputValidationValues NormalizeValidationByType(
            TemplateCustomInputType type,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue)
        {
            return type switch
            {
                TemplateCustomInputType.String => new CustomInputValidationValues
                {
                    MinLength = minLength,
                    MaxLength = maxLength,
                    MinValue = null,
                    MaxValue = null
                },

                TemplateCustomInputType.Integer => new CustomInputValidationValues
                {
                    MinLength = null,
                    MaxLength = null,
                    MinValue = minValue,
                    MaxValue = maxValue
                },

                _ => new CustomInputValidationValues()
            };
        }

        private sealed class CustomInputValidationValues
        {
            public int? MinLength { get; init; }
            public int? MaxLength { get; init; }
            public int? MinValue { get; init; }
            public int? MaxValue { get; init; }
        }
    }
}
