using BuildingBlock.Domain.EntitiesHelper;
using CustomerSurvey.Domain.Enums;

namespace CustomerSurvey.Domain.Entities
{
    public sealed class Template : AggregateRoot<Guid>
    {
        private readonly List<TemplateQuestion> _templateQuestions = new();
        private readonly List<TemplateCustomInput> _customInputs = new();

        public Guid BranchId { get; private set; }
        public Branch Branch { get; private set; } = null!;

        public string NameEn { get; private set; } = string.Empty;
        public string? NameAr { get; private set; }
        public string? Description { get; private set; }

        public DateTime ActiveFrom { get; private set; }
        public DateTime? ExpireTo { get; private set; }

        public TemplateStatus Status { get; private set; }
        public bool IsActive { get; private set; }

        public Guid CreatedByApplicationUserId { get; private set; }

        public IReadOnlyCollection<TemplateQuestion> TemplateQuestions =>
            _templateQuestions.AsReadOnly();

        public IReadOnlyCollection<TemplateCustomInput> CustomInputs =>
            _customInputs.AsReadOnly();

        private Template()
        {
        }

        public static Template Create(
            Guid branchId,
            string nameEn,
            string? nameAr,
            string? description,
            DateTime activeFrom,
            DateTime? expireTo,
            Guid createdByApplicationUserId)
        {
            return new Template
            {
                Id = Guid.NewGuid(),
                BranchId = branchId,
                NameEn = nameEn.Trim(),
                NameAr = string.IsNullOrWhiteSpace(nameAr) ? null : nameAr.Trim(),
                Description = string.IsNullOrWhiteSpace(description) ? null : description.Trim(),
                ActiveFrom = activeFrom,
                ExpireTo = expireTo,
                Status = TemplateStatus.Draft,
                IsActive = true,
                CreatedByApplicationUserId = createdByApplicationUserId
            };
        }

        public void Update(
            string nameEn,
            string? nameAr,
            string? description,
            DateTime activeFrom,
            DateTime? expireTo)
        {
            NameEn = nameEn.Trim();
            NameAr = string.IsNullOrWhiteSpace(nameAr) ? null : nameAr.Trim();
            Description = string.IsNullOrWhiteSpace(description) ? null : description.Trim();
            ActiveFrom = activeFrom;
            ExpireTo = expireTo;
        }

        public bool IsCurrentlyAvailable(DateTime utcNow)
        {
            return IsActive &&
                   ActiveFrom <= utcNow &&
                   (!ExpireTo.HasValue || ExpireTo.Value > utcNow);
        }

        public void AddCustomInput(TemplateCustomInput customInput)
        {
            if (_customInputs.Any(x => x.Name == customInput.Name && x.IsActive))
            {
                return;
            }

            _customInputs.Add(customInput);
        }

        public void Activate()
        {
            if (!IsActive)
            {
                return;
            }

            Status = TemplateStatus.Active;
        }

        public void Deactivate()
        {
            if (!IsActive)
            {
                return;
            }

            IsActive = false;
            Status = TemplateStatus.Inactive;
        }

        public void ReturnToDraft()
        {
            if (!IsActive)
            {
                return;
            }

            Status = TemplateStatus.Draft;
        }

        public void Restore()
        {
            if (IsActive)
            {
                return;
            }

            IsActive = true;
            Status = TemplateStatus.Draft;
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.Domain\Entities\TemplateCustomInput.cs */
using BuildingBlock.Domain.EntitiesHelper;
using CustomerSurvey.Domain.Enums;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.Domain.Entities
{
    public sealed class TemplateCustomInput : Entity<Guid>
    {
        public Guid TemplateId { get; private set; }
        public Template Template { get; private set; } = null!;

        public string Name { get; private set; } = string.Empty;
        public string? LabelEn { get; private set; }
        public string? LabelAr { get; private set; }

        public TemplateCustomInputType Type { get; private set; }

        public bool IsRequired { get; private set; }

        public int? MinLength { get; private set; }
        public int? MaxLength { get; private set; }

        public int? MinValue { get; private set; }
        public int? MaxValue { get; private set; }

        public int Order { get; private set; }

        public bool IsActive { get; private set; }

        public Guid CreatedByApplicationUserId { get; private set; }

        private TemplateCustomInput()
        {
        }

        public static TemplateCustomInput Create(
            Guid templateId,
            string name,
            string? labelEn,
            string? labelAr,
            TemplateCustomInputType type,
            bool isRequired,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue,
            int order,
            Guid createdByApplicationUserId)
        {
            var normalizedValidation = NormalizeValidationByType(
                type,
                minLength,
                maxLength,
                minValue,
                maxValue);

            return new TemplateCustomInput
            {
                Id = Guid.NewGuid(),
                TemplateId = templateId,
                Name = name.Trim(),
                LabelEn = string.IsNullOrWhiteSpace(labelEn) ? null : labelEn.Trim(),
                LabelAr = string.IsNullOrWhiteSpace(labelAr) ? null : labelAr.Trim(),
                Type = type,
                IsRequired = isRequired,
                MinLength = normalizedValidation.MinLength,
                MaxLength = normalizedValidation.MaxLength,
                MinValue = normalizedValidation.MinValue,
                MaxValue = normalizedValidation.MaxValue,
                Order = order,
                IsActive = true,
                CreatedByApplicationUserId = createdByApplicationUserId
            };
        }

        public void Update(
            string name,
            string? labelEn,
            string? labelAr,
            TemplateCustomInputType type,
            bool isRequired,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue,
            int order)
        {
            var normalizedValidation = NormalizeValidationByType(
                type,
                minLength,
                maxLength,
                minValue,
                maxValue);

            Name = name.Trim();
            LabelEn = string.IsNullOrWhiteSpace(labelEn) ? null : labelEn.Trim();
            LabelAr = string.IsNullOrWhiteSpace(labelAr) ? null : labelAr.Trim();
            Type = type;
            IsRequired = isRequired;
            MinLength = normalizedValidation.MinLength;
            MaxLength = normalizedValidation.MaxLength;
            MinValue = normalizedValidation.MinValue;
            MaxValue = normalizedValidation.MaxValue;
            Order = order;
        }

        public void ChangeOrder(int order)
        {
            Order = order;
        }

        public void Deactivate()
        {
            IsActive = false;
        }

        public void Restore()
        {
            IsActive = true;
        }

        private static CustomInputValidationValues NormalizeValidationByType(
            TemplateCustomInputType type,
            int? minLength,
            int? maxLength,
            int? minValue,
            int? maxValue)
        {
            return type switch
            {
                TemplateCustomInputType.String => new CustomInputValidationValues
                {
                    MinLength = minLength,
                    MaxLength = maxLength,
                    MinValue = null,
                    MaxValue = null
                },

                TemplateCustomInputType.Integer => new CustomInputValidationValues
                {
                    MinLength = null,
                    MaxLength = null,
                    MinValue = minValue,
                    MaxValue = maxValue
                },

                _ => new CustomInputValidationValues()
            };
        }

        private sealed class CustomInputValidationValues
        {
            public int? MinLength { get; init; }
            public int? MaxLength { get; init; }
            public int? MinValue { get; init; }
            public int? MaxValue { get; init; }
        }
    }
}
