using Microsoft.AspNetCore.Authorization;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.infrastructure.Authorization
{
    public class PermissionAuthorizationHandler : AuthorizationHandler<PermissionRequirement>
    {
        protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, PermissionRequirement requirement)
        {
            var userPermissions = context.User.FindAll("permission").Select(c => c.Value).ToHashSet(StringComparer.OrdinalIgnoreCase);

            bool hasAnyPermission = requirement.Permissions.Any(p => userPermissions.Contains(p));

            if (hasAnyPermission)
            {
                context.Succeed(requirement);
            }

            return Task.CompletedTask;
        }
    }

    public class PermissionRequirement : IAuthorizationRequirement
    {
        public List<string> Permissions { get; }

        public PermissionRequirement(IEnumerable<string> permissions)
        {
            Permissions = permissions.Select(p => p.Trim()).ToList();
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.infrastructure\Authorization\PermissionPolicyProvider.cs */
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Options;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.infrastructure.Authorization
{
    public class PermissionPolicyProvider : IAuthorizationPolicyProvider
    {
        private const string POLICY_PREFIX = "PERMISSION_";
        public DefaultAuthorizationPolicyProvider FallbackPolicyProvider { get; }

        public PermissionPolicyProvider(IOptions<AuthorizationOptions> options)
        {
            FallbackPolicyProvider = new DefaultAuthorizationPolicyProvider(options);
        }

        public Task<AuthorizationPolicy> GetDefaultPolicyAsync()
            => FallbackPolicyProvider.GetDefaultPolicyAsync();

        public Task<AuthorizationPolicy?> GetFallbackPolicyAsync()
            => FallbackPolicyProvider.GetFallbackPolicyAsync();

        public Task<AuthorizationPolicy?> GetPolicyAsync(string policyName)
        {
            if (policyName.StartsWith(POLICY_PREFIX))
            {
                var permissionSegment = policyName.Substring(POLICY_PREFIX.Length);
                var permissions = permissionSegment.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

                var policy = new AuthorizationPolicyBuilder()
                    .RequireAuthenticatedUser()
                    .AddRequirements(new PermissionRequirement(permissions))
                    .Build();

                return Task.FromResult<AuthorizationPolicy?>(policy);
            }

            return FallbackPolicyProvider.GetPolicyAsync(policyName);
        }
    }
}
/* FILE: E:\Customer Servey\CustomerSurvey.infrastructure\BackgroundJobs\Templates\ExpireTemplatesBackgroundService.cs */
using CustomerSurvey.Application.Abstraction.Presistence;
using CustomerSurvey.Domain.Entities;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CustomerSurvey.infrastructure.BackgroundJobs.Templates
{
    internal sealed class ExpireTemplatesBackgroundService : BackgroundService
    {
        private static readonly TimeSpan Period = TimeSpan.FromHours(1);

        private readonly IServiceScopeFactory _scopeFactory;
        private readonly ILogger<ExpireTemplatesBackgroundService> _logger;

        public ExpireTemplatesBackgroundService(
            IServiceScopeFactory scopeFactory,
            ILogger<ExpireTemplatesBackgroundService> logger)
        {
            _scopeFactory = scopeFactory
                ?? throw new ArgumentNullException(nameof(scopeFactory));

            _logger = logger
                ?? throw new ArgumentNullException(nameof(logger));
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            await ExpireTemplatesAsync(stoppingToken);

            using var timer = new PeriodicTimer(Period);

            while (await timer.WaitForNextTickAsync(stoppingToken))
            {
                await ExpireTemplatesAsync(stoppingToken);
            }
        }

        private async Task ExpireTemplatesAsync(CancellationToken cancellationToken)
        {
            try
            {
                using var scope = _scopeFactory.CreateScope();

                var templateReadRepository = scope.ServiceProvider
                    .GetRequiredService<IWriteReadRepository<Template>>();

                var templateWriteRepository = scope.ServiceProvider
                    .GetRequiredService<IWriteRepository<Template>>();

                var unitOfWork = scope.ServiceProvider
                    .GetRequiredService<IUnitOfWork>();

                var utcNow = DateTime.UtcNow;

                var expiredTemplates = await templateReadRepository.ListAsync(
                    new GetExpiredActiveTemplatesSpec(utcNow),
                    cancellationToken);

                if (expiredTemplates.Count == 0)
                {
                    return;
                }

                foreach (var template in expiredTemplates)
                {
                    template.Deactivate();
                    templateWriteRepository.Update(template);
                }

                await unitOfWork.SaveChangesAsync(cancellationToken);

                _logger.LogInformation(
                    "Expired {TemplatesCount} templates at {UtcNow}.",
                    expiredTemplates.Count,
                    utcNow);
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to expire templates.");
            }
        }
