            builder.HasIndex(x => new { x.BranchId, x.NameEn })
                .IsUnique()
                .HasFilter("[Scope] = 1 AND [BranchId] IS NOT NULL");

            builder.HasIndex(x => x.NameEn)
                .IsUnique()
                .HasDatabaseName("IX_AnonymousTemplate_Global_NameEn")
                .HasFilter("[Scope] = 2");

